"use strict";const s=require("./auth.js"),e=require("./request.js");async function r(){return s.withCustomerSession(()=>e.request("/addresses"))}exports.deleteAddress=async function(r){return s.withCustomerSession(()=>e.request(`/addresses/${r}`,"DELETE"))},exports.getAddress=async function(s){const e=(await r()).find(e=>e.id===s);if(!e)throw new Error("收货地址不存在或已删除");return e},exports.getAddresses=r,exports.saveAddress=async function(r,t){return s.withCustomerSession(()=>t?e.request(`/addresses/${t}`,"PUT",r):e.request("/addresses","POST",r))};
